# Extract JS from HTML and check syntax
node -e "
const fs = require('fs');
const html = fs.readFileSync('/workspace/games/wow-like-v2.html', 'utf8');
// Extract script content
const match = html.match(/<script>([\s\S]*)<\/script>/);
if(!match){console.log('No script found');process.exit(1);}
const js = match[1];
// Check for the fix
if(js.includes('let i1=0,j1=0'))console.log('✅ i1/j1 fix applied');
if(js.includes('let n0=0,n1=0,n2=0'))console.log('✅ n0/n1/n2 fix applied');
if(js.includes('_dot(i,x,y)'))console.log('✅ _dot method extracted');
// Check syntax
try{new Function(js);console.log('✅ No syntax errors in JS')}
catch(e){console.log('❌ Syntax error:',e.message)}
" 2>&1

