args.new_string:
function checkLevelUp(p){
  const needed=p.level*100;
  if(p.xp>=needed){
    p.xp-=needed;p.level++;
    p.maxHp+=20;p.maxMp+=10;
    p.hp=p.maxHp;p.mp=p.maxMp;
    p.atk+=3;p.def+=2;
    notify(`🎉 升级! Lv.${p.level}! 全属性提升!`);
    const lvlDiv=document.getElementById('level-up');
    lvlDiv.textContent=`⬆ LEVEL ${p.level} ⬆`;lvlDiv.className='show';
    setTimeout(()=>lvlDiv.className='',1500);
    updateHUD();

    // Check for advancement
    if(p.level===25 || p.level===50){
      setTimeout(()=>triggerAdvancement(p), 300);
    }

    // Check for multiple level ups
    checkLevelUp(p);
  }
}

function triggerAdvancement(p){
  const adv=ADVANCEMENTS[p.cls];
  const tier=p.advancement===0?adv.t1:adv.t2;
  if(!tier)return;

  const screen=document.getElementById('advancement-screen');
  document.getElementById('adv-icon').textContent=tier.icon;
  document.getElementById('adv-title').textContent=`${tier.name}`;
  document.getElementById('adv-desc').textContent=tier.desc;

  // Stats bonus display
  const sb=tier.statBonus;
  let bonusHtml='<div class="stat-line"><span>基础属性提升</span><span class="sv">⬆⬆⬆</span></div>';
  if(sb.hp)bonusHtml+=`<div class="stat-line"><span>❤️ 生命上限</span><span class="sv">+${sb.hp}</span></div>`;
  if(sb.mp)bonusHtml+=`<div class="stat-line"><span>💧 魔法上限</span><span class="sv">+${sb.mp}</span></div>`;
  if(sb.atkPct)bonusHtml+=`<div class="stat-line"><span>⚔️ 攻击力</span><span class="sv2">+${(sb.atkPct*100).toFixed(0)}%</span></div>`;
  if(sb.defPct)bonusHtml+=`<div class="stat-line"><span>🛡️ 防御力</span><span class="sv2">+${(sb.defPct*100).toFixed(0)}%</span></div>`;
  if(sb.critRate)bonusHtml+=`<div class="stat-line"><span>💥 暴击率</span><span class="sv2">+${(sb.critRate*100).toFixed(0)}%</span></div>`;
  if(sb.critDmg)bonusHtml+=`<div class="stat-line"><span>💢 暴击伤害</span><span class="sv2">+${(sb.critDmg*100).toFixed(0)}%</span></div>`;
  if(sb.spdPct)bonusHtml+=`<div class="stat-line"><span>💨 移动速度</span><span class="sv2">+${(sb.spdPct*100).toFixed(0)}%</span></div>`;
  document.getElementById('adv-bonus').innerHTML=bonusHtml;

  // Skill display
  const skDiv=document.getElementById('adv-skills');
  skDiv.innerHTML='';
  for(const su of tier.skillUpgrades){
    const base=p.skills.find(s=>s.id===su.id);
    if(!base)continue;
    const el=document.createElement('div');el.className='askill';
    el.innerHTML=`<div class="asi">${su.icon}</div><div class="asn">${su.name}</div><div class="asup">${base.name}→升级</div>`;
    skDiv.appendChild(el);
  }

  screen.style.display='flex';
  G.gameStarted=false; // Pause game during advancement
}

function closeAdvancement(){
  const p=G.player;
  const adv=ADVANCEMENTS[p.cls];
  const tier=p.advancement===0?adv.t1:adv.t2;
  if(!tier)return;

  // Apply stat bonuses
  const sb=tier.statBonus;
  if(sb.hp){p.maxHp+=sb.hp;p.hp=p.maxHp;}
  if(sb.mp){p.maxMp+=sb.mp;p.mp=p.maxMp;}
  if(sb.atkPct)p.atk=Math.floor(p.atk*(1+sb.atkPct));
  if(sb.defPct)p.def=Math.floor(p.def*(1+sb.defPct));
  if(sb.critRate)p.critRate+=sb.critRate;
  if(sb.critDmg+=sb.critDmg);
  if(sb.spdPct)p.speed=Math.floor(p.speed*(1+sb.spdPct));

  // Upgrade skills
  for(const su of tier.skillUpgrades){
    const skill=p.skills.find(s=>s.id===su.id);
    if(!skill)continue;
    skill.name=su.name;
    skill.icon=su.icon;
    if(su.dmg!==undefined)skill.dmg=su.dmg;
    if(su.range!==undefined)skill.range=su.range;
    if(su.desc!==undefined)skill.desc=su.desc;
    if(su.cd!==undefined)skill.cd=su.cd;
  }

  // Update advancement state
  p.advancement++;
  p.advName=tier.name;
  p.advIcon=tier.icon;

  const tierName=p.advancement===1?'第一阶·':'第二阶·';
  notify(`⚡⚡⚡ 进阶完成！${tierName}${tier.name}`);

  document.getElementById('advancement-screen').style.display='none';
  G.gameStarted=true;
  updateHUD();
  updateSkillBar();

  // Rewards for advancing
  p.gold+=p.advancement===1?100:300;
  notify(`💰 进阶奖励: +${p.advancement===1?100:300} 金币`);
}

